quickRef.usagePattern:
// vault feature 调用 trade helper
import { notifyVaultDepositCompleted, notifyVaultWithdrawSuccess, notifyVaultClaimSuccess } from '@/features/trade';

// useSubmitVaultDeposit.onSuccess
notifyVaultDepositCompleted(input.amount, input.token.symbolDisplay);
setTimeout(() => invalidateVaultMutationQueries(qc, address), 3000);
setTimeout(() => invalidateVaultMutationQueries(qc, address), 5000);
setTimeout(() => invalidateVaultMutationQueries(qc, address), 9000);

// useSubmitVaultWithdraw.onSuccess(sMAG7 路径独有)
if (params.token === 'sMAG7') notifyVaultWithdrawSuccess(params.amount, 'sMAG7.ssi');
// MAG7 路径不弹,等 WS sodex_call_for type=1 Success

// 入口(vault SLP 区域 / VaultStats)
import { openVaultUnstakeDialog } from '@/features/vault';
await openVaultUnstakeDialog();
// → 弹窗内 form.submit({ amount }) 自动走 smart-transfer + CallForPermit
// → onSuccess 不弹 toast,等 WS sodex_call_for type=1
// → onError 由 handleUnstakeServiceError 弹 toast

// 入口(vault SLP 区域 / VaultStats)
import { openVaultClaimDialog } from '@/features/vault';
await openVaultClaimDialog();
// → 弹窗内 form.submit({ amount }) 自动走 CallForPermit
// → onSuccess 不弹 toast,等 WS sodex_call_for type=2
// → onError 由 handleClaimServiceError 弹 toast

// 入口(VaultHeader)
import { openVaultWithdrawDialog } from '@/features/vault';
await openVaultWithdrawDialog();
// → form.submit({ token: 'MAG7'|'sMAG7', amount, slpDecimals })
// → MAG7+cooldown 弹 Confirmation Dialog 二次确认
// → Step A executeVaultRedeem(2 次签名) → if sMAG7 done / else Step B executeUnstakePermit
// → onSuccess: sMAG7 主动 notifyVaultWithdrawSuccess + 3 次延迟 invalidate
//             MAG7 不弹,等 WS sodex_call_for type=1

// 入口(VaultStats/Header/SLPViewModel)
import { openVaultDepositDialog } from '@/features/vault';
await openVaultDepositDialog({ defaultChain: 'BASE_ETH', defaultToken: ..., defaultFrom: 'SPOT' });

// 流程: idle <Form/> → handleSubmit(检查 chainId,切链)→ tradingStatus='preview' <Preview/>
//      → handleConfirmDeposit → submission.submit({chain,token,from,amount,account,isNewUser})
//      → tradingStatus='trading' <Trading/>
//      → machine.start() 走 3 层 reducer 状态机
//      → topState='completed' → notifyVaultDepositCompleted + 3 次延迟 invalidate(3s/5s/9s)
//      → 1s 后 modalClose()
